// Lists today's videos that were not posted to TikTok yet.
// Folder layout: /data/videos/Posts/<YYYY-MM-DD>/*.mp4
const fs = require('fs');

const TIMEZONE = 'UTC'; // change to your time zone, e.g. 'America/New_York'
const BASE = '/data/videos/Posts';

const today = new Intl.DateTimeFormat('en-CA', { timeZone: TIMEZONE }).format(new Date());
const dir = BASE + '/' + today;
if (!fs.existsSync(dir)) return [];

let tags = '';
try {
  tags = fs.readFileSync(BASE + '/tags-tiktok.txt', 'utf8').replace(/\s+/g, ' ').trim();
} catch (e) {}

const items = [];
for (const file of fs.readdirSync(dir).sort()) {
  if (!file.toLowerCase().endsWith('.mp4')) continue;
  const name = file.slice(0, -4);
  const marker = dir + '/' + name + '.tiktok.ok';
  if (fs.existsSync(marker)) continue;
  items.push({ json: { dir, file, path: dir + '/' + file, name, marker, tags } });
}
return items;

// Returns a valid access token, refreshing it with the saved refresh_token when needed.
// The token file is created by scripts/authorize.js.
const fs = require('fs');
const https = require('https');

const TOKEN_FILE = '/home/node/.n8n/tiktok.json';

let creds;
try {
  creds = JSON.parse(fs.readFileSync(TOKEN_FILE, 'utf8'));
} catch (e) {
  throw new Error('Missing ' + TOKEN_FILE + ': run scripts/authorize.js first');
}

const post = (url, body) => new Promise((resolve, reject) => {
  const req = https.request(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'Content-Length': Buffer.byteLength(body) }
  }, res => {
    const parts = [];
    res.on('data', d => parts.push(d));
    res.on('end', () => resolve(JSON.parse(Buffer.concat(parts).toString())));
  });
  req.on('error', reject);
  req.end(body);
});

if (!creds.access_token || Date.now() > creds.expires_at - 60000) {
  const r = await post('https://open.tiktokapis.com/v2/oauth/token/', new URLSearchParams({
    client_key: creds.client_key,
    client_secret: creds.client_secret,
    grant_type: 'refresh_token',
    refresh_token: creds.refresh_token
  }).toString());
  if (!r.access_token) throw new Error('TikTok refused the refresh: ' + JSON.stringify(r));
  creds.access_token = r.access_token;
  creds.refresh_token = r.refresh_token || creds.refresh_token;
  creds.expires_at = Date.now() + r.expires_in * 1000;
  fs.writeFileSync(TOKEN_FILE, JSON.stringify(creds, null, 2));
}

return $input.all().map(i => ({ json: { ...i.json, access_token: creds.access_token } }));

// Posts one video: init -> upload -> status check -> marker file.
const fs = require('fs');
const https = require('https');

const item = $input.first().json;

// An app that has not passed the TikTok audit can only post with SELF_ONLY.
// After approval, change it to 'PUBLIC_TO_EVERYONE'.
const PRIVACY = 'SELF_ONLY';

const request = (url, method, headers, body) => new Promise((resolve, reject) => {
  const req = https.request(url, { method, headers: { ...headers, 'Content-Length': body.length } }, res => {
    const parts = [];
    res.on('data', d => parts.push(d));
    res.on('end', () => resolve({ status: res.statusCode, text: Buffer.concat(parts).toString() }));
  });
  req.on('error', reject);
  req.end(body);
});

const api = async (url, body) => {
  const r = await request(url, 'POST', {
    Authorization: 'Bearer ' + item.access_token,
    'Content-Type': 'application/json; charset=UTF-8'
  }, Buffer.from(JSON.stringify(body)));
  return JSON.parse(r.text);
};

const video = fs.readFileSync(item.path);
const size = video.length;
const chunk = size <= 64 * 1024 * 1024 ? size : 50 * 1024 * 1024;
const chunks = Math.floor(size / chunk);

const init = await api('https://open.tiktokapis.com/v2/post/publish/video/init/', {
  post_info: { title: item.tags, privacy_level: PRIVACY, disable_duet: false, disable_comment: false, disable_stitch: false },
  source_info: { source: 'FILE_UPLOAD', video_size: size, chunk_size: chunk, total_chunk_count: chunks }
});
if (!init.data || !init.data.upload_url) throw new Error('init failed: ' + JSON.stringify(init));
const { upload_url, publish_id } = init.data;

for (let i = 0; i < chunks; i++) {
  const start = i * chunk;
  const end = i === chunks - 1 ? size : start + chunk;
  const r = await request(upload_url, 'PUT', {
    'Content-Type': 'video/mp4',
    'Content-Range': 'bytes ' + start + '-' + (end - 1) + '/' + size
  }, video.subarray(start, end));
  if (r.status >= 300) throw new Error('upload failed: ' + r.status + ' ' + r.text);
}

let status = '';
for (let attempt = 0; attempt < 12; attempt++) {
  await new Promise(r => setTimeout(r, 10000));
  const s = await api('https://open.tiktokapis.com/v2/post/publish/status/fetch/', { publish_id });
  status = (s.data && s.data.status) || '';
  if (status === 'PUBLISH_COMPLETE') break;
  if (status === 'FAILED') throw new Error('TikTok failed: ' + JSON.stringify(s.data));
}

fs.writeFileSync(item.marker, new Date().toISOString() + ' ' + publish_id + ' ' + status + '\n');
return [{ json: { file: item.file, publish_id, status } }];
